-- 재고 입출고 이력 + 환불 대기/실패 더미. pawcast_seed_3y.sql 실행 후 1회만 실행하세요 (두 번 실행하면 중복).
-- inventory_transactions: 주문(OUTBOUND), 취소 환불(RETURN), 발주 입고(INBOUND), 재고 실사(ADJUSTMENT). 각 variant 의 마지막 stock_after = 현재 product_variants.stock 와 일치합니다.
-- transaction_type / reference_type 값은 가상 값입니다(소스에 엔티티 없음). 백엔드 값과 다르면 문자열만 바꾸세요.
SET client_encoding TO 'UTF8';
BEGIN;

-- 환불 승인 대기(PENDING) 28건: 최근 12일 내 배송완료 주문 중 아직 환불 없는 결제
SELECT p.id, NULL, 'DEMO-REFUND-REQ-' || p.id, p.amount,
       (ARRAY['상품 불량','오배송','배송 중 파손','단순 변심','기대와 다름','사이즈·용량 착오'])[1 + abs(hashtext(p.id::text || 'r')) % 6],
       'PENDING', LEAST(TIMESTAMP '2026-11-20 10:25:00', s.delivered_at::timestamp + (abs(hashtext(p.id::text || 't')) % 72 + 2) * interval '1 hour'), NULL
FROM payments p JOIN orders o ON o.id=p.order_id JOIN shipments s ON s.order_id=o.id
WHERE p.status='PAID' AND o.status='DELIVERED' AND s.delivered_at > TIMESTAMP '2026-11-08' AND NOT EXISTS (SELECT 1 FROM refunds r WHERE r.payment_id=p.id)
ORDER BY abs(hashtext(p.id::text || 'sel')) LIMIT 28;

-- 환불 실패(FAILED) 6건: 지난 60일 배송완료 주문
SELECT p.id, NULL, 'DEMO-REFUND-FAIL-' || p.id, p.amount, '단순 변심', 'FAILED', s.delivered_at::timestamp + interval '30 hours', NULL
FROM payments p JOIN orders o ON o.id=p.order_id JOIN shipments s ON s.order_id=o.id
WHERE p.status='PAID' AND o.status='DELIVERED' AND s.delivered_at BETWEEN TIMESTAMP '2026-09-20' AND TIMESTAMP '2026-11-05' AND NOT EXISTS (SELECT 1 FROM refunds r WHERE r.payment_id=p.id)
ORDER BY abs(hashtext(p.id::text || 'f')) LIMIT 6;
COMMIT;

-- 확인
SELECT transaction_type, count(*), sum(quantity_change) FROM inventory_transactions GROUP BY 1 ORDER BY 1;
SELECT count(*) AS mismatch_with_current_stock FROM product_variants v WHERE v.stock <> COALESCE((SELECT stock_after FROM inventory_transactions t WHERE t.variant_id=v.id ORDER BY created_at DESC, id DESC LIMIT 1), v.stock);
SELECT count(*) AS negative_stock_rows FROM inventory_transactions WHERE stock_before<0 OR stock_after<0;
SELECT status, count(*), sum(refund_amount) FROM refunds GROUP BY 1 ORDER BY 1;
